orage;\n    payload: {\n        key: string;\n    };\n}\n\nexport type GetLocalStorageMessageResponse = string | null | undefined;\n\nexport interface GetLocalStorageKeysMessage {\n    type: Action.getLocalStorageKeys;\n}\n\nexport type GetLocalStorageKeysMessageResponse = string[] | null | undefined;\n\nexport interface SetLocalStorageMessage {\n    type: Action.setLocalStorage;\n    payload: {\n        key: string;\n        value: string;\n    };\n}\n\nexport type SetLocalStorageMessageResponse = undefined;\n\nexport interface RemoveLocalStorageMessage {\n    type: Action.removeLocalStorage;\n    payload: {\n        key: string;\n    };\n}\n\nexport type RemoveLocalStorageMessageResponse = undefined;\n\nexport type ProtonMessages =\n    | GetLocalStorageMessage\n    | GetLocalStorageKeysMessage\n    | SetLocalStorageMessage\n    | RemoveLocalStorageMessage;\n\nexport type ProtonMessageResponses =\n    | GetLocalStorageMessageResponse\n    | GetLocalStorageKeysMessageResponse\n    | SetLocalStorageMessageResponse\n    | RemoveLocalStorageMessageResponse;\n","// eslint-disable-next-line max-classes-per-file\nexport class CrossStorageTimeoutError extends Error {\n    public trace = false;\n\n    constructor() {\n        super('Cross-storage timeout');\n        Object.setPrototypeOf(this, CrossStorageTimeoutError.prototype);\n    }\n}\n\nexport class CrossStorageUnsupportedError extends Error {\n    public trace = false;\n\n    constructor() {\n        super('Cross-storage unsupported');\n        Object.setPrototypeOf(this, CrossStorageUnsupportedError.prototype);\n    }\n}\n","export const setTestKeyValue = (window: Window) => {\n    try {\n        window.localStorage.setItem('cs', '1');\n    } catch (e: any) {\n        return undefined;\n    }\n};\n\nexport const getIsSupported = (value: any) => {\n    return value === '1';\n};\n\nexport const getTestKeyValue = (window: Window) => {\n    try {\n        return window.localStorage.getItem('cs');\n    } catch (e: any) {\n        return undefined;\n    }\n};\n","import { getSecondLevelDomain } from '@proton/shared/lib/helpers/url';\n\nimport { CrossStorageMessage, ResponseMessage } from './interface';\nimport { getTestKeyValue, setTestKeyValue } from './support';\n\nconst createHost = <Message, MessageResponse>(handler: (message: Message) => Promise<MessageResponse>) => {\n    const isEmbedded = window.location !== window.parent.location;\n    const hostSecondLevelDomain = getSecondLevelDomain(window.location.hostname);\n\n    if (!isEmbedded) {\n        throw new Error('Window not embedded');\n    }\n\n    const postMessage = (message: CrossStorageMessage, origin: string) => {\n        return window.parent.postMessage(message, origin);\n    };\n\n    postMessage({ type: 'init', payload: { value: getTestKeyValue(window) } }, '*');\n\n    const reply = (origin: string, payload: ResponseMessage<MessageResponse>) => {\n        postMessage(payload, origin);\n    };\n\n    window.addEventListener('message', (event: MessageEvent<CrossStorageMessage>) => {\n        const { source, data, origin } = event;\n        if (\n            source !== window.parent ||\n            getSecondLevelDomain(new URL(origin).hostname) !== hostSecondLevelDomain ||\n            data?.type !== 'message'\n        ) {\n            return;\n        }\n        handler(data.payload)\n            .then((response) => {\n                reply(origin, { id: data.id, type: 'response', status: 'success', payload: response });\n            })\n            .catch((e) => {\n                reply(origin, {\n                    id: data.id,\n                    type: 'response',\n                    status: 'error',\n                    payload: e,\n                });\n            });\n    });\n};\n\nexport const initMainHost = () => {\n    setTestKeyValue(window);\n};\n\nexport default createHost;\n","import type { enums } from '@proton/crypto';\n\nimport { EncryptionConfig } from './interfaces';\n\nexport const DEFAULT_T